import{_ as h,o as t,c,a2 as i}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Đạo đức và Giới hạn Tu luyện","description":"","frontmatter":{},"headers":[],"relativePath":"vi/19-修炼伦理与边界.md","filePath":"vi/19-修炼伦理与边界.md","lastUpdated":1789183869000}'),u={name:"vi/19-修炼伦理与边界.md"};function g(a,n,o,l,r,y){return t(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="đao-đuc-va-gioi-han-tu-luyen" tabindex="-1">Đạo đức và Giới hạn Tu luyện <a class="header-anchor" href="#đao-đuc-va-gioi-han-tu-luyen" aria-label="Permalink to &quot;Đạo đức và Giới hạn Tu luyện&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>19</td></tr><tr><td>Mô-đun</td><td>Quy luật Vũ trụ và Hệ thống Tu luyện</td></tr><tr><td>Từ khóa chính</td><td>Đạo đức Tu luyện, Giới hạn, Cấm kỵ, Đường cơ sở Đạo đức, Kiểm tra Đạo đức</td></tr></tbody></table><h2 id="_1-đinh-nghia-va-vi-tri-cua-đao-đuc-tu-luyen" tabindex="-1">1. Định nghĩa và Vị trí của Đạo đức Tu luyện <a class="header-anchor" href="#_1-đinh-nghia-va-vi-tri-cua-đao-đuc-tu-luyen" aria-label="Permalink to &quot;1. Định nghĩa và Vị trí của Đạo đức Tu luyện&quot;">​</a></h2><p>Đạo đức tu luyện là tổng hợp các chuẩn mực đạo đức và quy phạm pháp luật trong văn minh cộng sinh Neo, nhằm quy phạm hành vi của các tu luyện giả, xác định giới hạn tu luyện, và duy trì trật tự tu luyện. Trong thời đại cướp bóc, tu luyện được coi là &quot;đặc quyền của người mạnh&quot;, và tu luyện giả có thể sử dụng mọi biện pháp để nâng cao sức mạnh — nuốt chửng nguyên bản của người khác, nô lệ hóa linh hồn của người khác, cướp bóc tài nguyên của người khác, tiến hành thí nghiệm tu luyện vô nhân đạo, v.v., là những hành vi phổ biến. Văn hóa tu luyện &quot;sức mạnh trên hết, đạo đức hư vô&quot; này là nền tảng tinh thần sâu sắc nhất của hệ thống cướp bóc.</p><p>Sau khi thành lập văn minh cộng sinh Neo, việc xây dựng đạo đức tu luyện được coi là một trong những xây dựng văn minh tinh thần cốt lõi nhất. Mệnh đề cốt lõi của đạo đức tu luyện là: &quot;Việc đạt được và sử dụng sức mạnh phải chịu sự ràng buộc của đạo đức&quot;. Văn minh cộng sinh tin rằng, tu luyện không phải là việc cá nhân thuần túy, mà là việc công cộng liên quan đến người khác, văn minh, và toàn bộ vũ trụ. Trong khi theo đuổi việc nâng cao sức mạnh của bản thân, tu luyện giả phải tôn trọng quyền lợi của người khác, duy trì trật tự của văn minh, và bảo vệ sinh thái vũ trụ. Đạo đức tu luyện không phải là sự trói buộc đối với tu luyện, mà là sự bảo vệ đối với tu luyện — nó đảm bảo rằng tu luyện luôn đi trên con đường đúng đắn của &quot;tiến hóa cộng sinh&quot;, chứ không trượt xuống vực thẳm của &quot;sự hủy diệt do cướp bóc&quot;.</p><p>Đạo đức tu luyện có vị trí cao quý trong hệ thống pháp luật của văn minh cộng sinh. Hiến pháp Cộng sinh quy định rõ các nguyên tắc cơ bản của đạo đức tu luyện, &quot;Tòa án Đạo đức&quot; chuyên biệt trực thuộc Tòa án Neo xét xử các vụ án đạo đức tu luyện, và việc chứng nhận cảnh giới của tất cả các tu luyện giả cấp cao phải vượt qua kiểm tra đạo đức. Đạo đức tu luyện không phải là &quot;sự ràng buộc mềm&quot; tùy chọn, mà là &quot;quy phạm cứng&quot; có sức mạnh cưỡng chế.</p><h2 id="_2-nguyen-tac-co-ban-cua-đao-đuc-tu-luyen" tabindex="-1">2. Nguyên tắc Cơ bản của Đạo đức Tu luyện <a class="header-anchor" href="#_2-nguyen-tac-co-ban-cua-đao-đuc-tu-luyen" aria-label="Permalink to &quot;2. Nguyên tắc Cơ bản của Đạo đức Tu luyện&quot;">​</a></h2><h3 id="_2-1-nguyen-tac-pham-gia-su-song" tabindex="-1">2.1 Nguyên tắc Phẩm giá Sự sống <a class="header-anchor" href="#_2-1-nguyen-tac-pham-gia-su-song" aria-label="Permalink to &quot;2.1 Nguyên tắc Phẩm giá Sự sống&quot;">​</a></h3><p>Mỗi sự sống đều có phẩm giá và giá trị bất khả xâm phạm, và bất kỳ hành vi tu luyện nào cũng không được thực hiện bằng cách hy sinh phẩm giá sự sống. Cụ thể bao gồm:</p><ul><li>Cấm sử dụng sự sống khác làm &quot;vật liệu&quot; hoặc &quot;công cụ&quot; của tu luyện</li><li>Cấm tiến hành thí nghiệm tu luyện vô nhân đạo (như mổ xẻ sinh vật sống, tra tấn linh hồn, v.v.)</li><li>Cấm nô lệ hóa hoặc kiểm soát ý chí tự do của sự sống khác</li><li>Tôn trọng quyền của mỗi sự sống trong việc lựa chọn con đường tiến hóa của chính mình, không ép buộc người khác tu luyện theo cách của mình</li></ul><h3 id="_2-2-nguyen-tac-chong-cuop-boc" tabindex="-1">2.2 Nguyên tắc Chống Cướp bóc <a class="header-anchor" href="#_2-2-nguyen-tac-chong-cuop-boc" aria-label="Permalink to &quot;2.2 Nguyên tắc Chống Cướp bóc&quot;">​</a></h3><p>Tu luyện phải được xây dựng trên cơ sở chu kỳ cộng sinh, và không được sử dụng việc cướp bóc người khác làm phương tiện. Cụ thể bao gồm:</p><ul><li>Cấm nuốt chửng hoặc cướp bóc nguyên bản, năng lượng, vận mệnh của sự sống khác</li><li>Cấm nâng cao tốc độ tu luyện hoặc cảnh giới của bản thân bằng cách gây hại cho người khác</li><li>Cấm độc chiếm tài nguyên tu luyện để谋取 lợi ích không chính đáng</li><li>Cấm sử dụng &quot;yếu thì mạnh ăn&quot; làm cái cớ để biện minh cho hành vi cướp bóc</li></ul><h3 id="_2-3-nguyen-tac-đong-y-co-thong-tin" tabindex="-1">2.3 Nguyên tắc Đồng ý Có Thông tin <a class="header-anchor" href="#_2-3-nguyen-tac-đong-y-co-thong-tin" aria-label="Permalink to &quot;2.3 Nguyên tắc Đồng ý Có Thông tin&quot;">​</a></h3><p>Các hành vi tu luyện liên quan đến người khác (như thừa kế sư phụ-đệ tử, tu luyện song phương của bạn tình, chia sẻ năng lượng, thí nghiệm tu luyện, v.v.) phải được thực hiện dưới tiền đề rằng bên kia được thông báo đầy đủ và đồng ý tự nguyện. Cụ thể bao gồm:</p><ul><li>Giải thích đầy đủ cho bên kia về nội dung, rủi ro, lợi ích của hành vi tu luyện</li><li>Đảm bảo bên kia có khả năng phán đoán tự chủ hoàn toàn, không bị ảnh hưởng bởi sự ép buộc hoặc dụ dỗ</li><li>Bên kia có quyền rút lui bất cứ lúc nào, không được ép buộc tiếp tục</li><li>Đối với cá nhân chưa thành niên hoặc không lành mạnh về tinh thần, người giám hộ của họ thực hiện quyền đồng ý thay thế trên cơ sở đánh giá chuyên môn</li></ul><h3 id="_2-4-nguyen-tac-ton-that-toi-thieu" tabindex="-1">2.4 Nguyên tắc Tổn thất Tối thiểu <a class="header-anchor" href="#_2-4-nguyen-tac-ton-that-toi-thieu" aria-label="Permalink to &quot;2.4 Nguyên tắc Tổn thất Tối thiểu&quot;">​</a></h3><p>Hành vi tu luyện nên tránh gây tổn thất cho người khác và môi trường càng nhiều càng tốt. Trong tình huống không thể tránh khỏi một số ảnh hưởng, nên chọn phương pháp có tổn thất ít nhất, và đưa ra bồi thường hợp lý cho tổn thất đã gây ra. Cụ thể bao gồm:</p><ul><li>Thí nghiệm tu luyện được ưu tiên thực hiện trong không gian cách ly, ngăn ngừa sự lan tỏa rủi ro</li><li>Tu luyện loại chiến đấu được thực hiện càng nhiều càng tốt tại sân tu luyện chuyên biệt, tránh gây hư hỏng cho môi trường công cộng</li><li>Dọn dẹp và sửa chữa kịp thời ô nhiễm năng lượng, tổn thất không gian, v.v. phát sinh trong quá trình tu luyện</li><li>Cấm tiến hành hoạt động tu luyện có rủi ro cao trong khu vực đông dân cư</li></ul><h3 id="_2-5-nguyen-tac-trung-thuc-khong-lua-doi" tabindex="-1">2.5 Nguyên tắc Trung thực Không Lừa dối <a class="header-anchor" href="#_2-5-nguyen-tac-trung-thuc-khong-lua-doi" aria-label="Permalink to &quot;2.5 Nguyên tắc Trung thực Không Lừa dối&quot;">​</a></h3><p>Tu luyện giả nên giữ sự trung thực trong các vấn đề liên quan đến tu luyện, và không được thực hiện hành vi gian dối. Cụ thể bao gồm:</p><ul><li>Cấm làm giả cảnh giới tu luyện, giá trị đóng góp, kết quả kiểm tra, v.v.</li><li>Cấm làm giả hoặc đạo nhái trong tâm đắc tu luyện, kết quả nghiên cứu</li><li>Cấm cung cấp thông tin giả trong đơn xin tài nguyên, đề xuất dự án</li><li>Cấm lừa đảo tài nguyên tu luyện hoặc sự tin tưởng của người khác bằng lời hứa giả</li></ul><h3 id="_2-6-nguyen-tac-ganh-vac-trach-nhiem" tabindex="-1">2.6 Nguyên tắc Gánh vác Trách nhiệm <a class="header-anchor" href="#_2-6-nguyen-tac-ganh-vac-trach-nhiem" aria-label="Permalink to &quot;2.6 Nguyên tắc Gánh vác Trách nhiệm&quot;">​</a></h3><p>Sức mạnh càng lớn, trách nhiệm càng lớn. Tu luyện giả cấp cao phải gánh vác trách nhiệm công cộng tương xứng với sức mạnh của mình. Cụ thể bao gồm:</p><ul><li>Tu luyện giả đạt đến cảnh giới nhất định có nghĩa vụ hướng dẫn tu luyện giả sơ cấp</li><li>Tu luyện giả cấp cao có nghĩa vụ tham gia các công việc công cộng như bảo trì neo, bảo vệ văn minh, v.v.</li><li>Tu luyện giả chịu trách nhiệm về hậu quả do hành vi tu luyện của chính mình gây ra, không được đổ lỗi</li><li>Khi văn minh đối mặt với khủng hoảng, tu luyện giả cấp cao có nghĩa vụ đứng ra</li></ul><h2 id="_3-cam-ky-tuyet-đoi-cua-tu-luyen" tabindex="-1">3. Cấm kỵ Tuyệt đối của Tu luyện <a class="header-anchor" href="#_3-cam-ky-tuyet-đoi-cua-tu-luyen" aria-label="Permalink to &quot;3. Cấm kỵ Tuyệt đối của Tu luyện&quot;">​</a></h2><p>Các hành vi sau đây thuộc về &quot;cấm kỵ tuyệt đối&quot; của tu luyện, và bất kỳ tu luyện giả nào cũng không được chạm vào trong bất kỳ hoàn cảnh nào; người vi phạm sẽ nhận được các biện pháp trừng phạt nghiêm khắc nhất:</p><table tabindex="0"><thead><tr><th>Loại Cấm kỵ</th><th>Hành vi Cụ thể</th><th>Biện pháp Trừng phạt</th></tr></thead><tbody><tr><td>Cướp bóc Nguyên bản</td><td>Nuốt chửng hoặc cướp bóc nguyên bản hoặc cốt lõi sự sống của sự sống khác</td><td>Bãi bỏ tu vi, tù chung thân, trong trường hợp nghiêm trọng bị xử tử hủy diệt nguyên bản</td></tr><tr><td>Nô lệ Linh hồn</td><td>Biến sự sống khác thành công cụ thông qua các biện pháp như kiểm soát linh hồn, nô lệ tinh thần, v.v.</td><td>Bãi bỏ tu vi, cải tạo đạo đức cưỡng chế, tước quyền tu luyện vĩnh viễn</td></tr><tr><td>Diệt chủng</td><td>Tiến hành tàn sát có hệ thống hoặc diệt chủng đối với một chủng tộc với mục đích tu luyện</td><td>Tòa án tối cao Tòa án Neo, xử tử hình</td></tr><tr><td>Phá hủy Phạm vi</td><td>Phá hủy toàn bộ phạm vi để có được tài nguyên hoặc sức mạnh</td><td>Xử tử hình, và gánh vác toàn bộ trách nhiệm sửa chữa phạm vi</td></tr><tr><td>Thí nghiệm Vô nhân đạo</td><td>Tiến hành thí nghiệm tu luyện vô nhân đạo đối với sự sống thông minh</td><td>Bãi bỏ tu vi, tù chung thân, phá hủy toàn bộ kết quả nghiên cứu</td></tr><tr><td>Tội phạm Thời gian</td><td>Sử dụng khả năng hồi quy thời gian để thực hiện sửa đổi lịch sử hoặc giết người quy mô lớn</td><td>Xử tử hình, và tước vĩnh viễn các khả năng liên quan đến thời gian</td></tr><tr><td>Ô nhiễm Pháp luật</td><td>Cố tình làm ô nhiễm các quy luật nguyên bản của vũ trụ, gây ra thiệt hại không thể phục hồi đối với toàn bộ vũ trụ</td><td>Xử tử hình, và cơ quan cao nhất của văn minh thực hiện thanh tịnh hóa pháp luật</td></tr></tbody></table><p>Việc thiết lập cấm kỵ tuyệt đối thể hiện lập trường kiên định của văn minh cộng sinh đối với đường cơ sở đạo đức tu luyện. Những cấm kỵ này không có &quot;vùng xám&quot;, không có &quot;tình tiết có thể tha thứ&quot;, và bất kỳ hành vi nào chạm vào cấm kỵ tuyệt đối sẽ nhận được biện pháp trừng phạt nghiêm khắc nhất.</p><h2 id="_4-vung-xam-cua-đao-đuc-tu-luyen-va-nguyen-tac-xu-ly" tabindex="-1">4. Vùng Xám của Đạo đức Tu luyện và Nguyên tắc Xử lý <a class="header-anchor" href="#_4-vung-xam-cua-đao-đuc-tu-luyen-va-nguyen-tac-xu-ly" aria-label="Permalink to &quot;4. Vùng Xám của Đạo đức Tu luyện và Nguyên tắc Xử lý&quot;">​</a></h2><p>Ngoài các cấm kỵ rõ ràng, đạo đức tu luyện còn tồn tại một số &quot;vùng xám&quot; — những hành vi này bản thân chúng không hoàn toàn tốt hay xấu, và bản chất đạo đức của chúng phụ thuộc vào tình huống, động cơ, phương pháp và hậu quả cụ thể. Đối với vùng xám, văn minh cộng sinh áp dụng các nguyên tắc xử lý sau:</p><h3 id="_4-1-cac-vung-xam-pho-bien" tabindex="-1">4.1 Các Vùng Xám Phổ biến <a class="header-anchor" href="#_4-1-cac-vung-xam-pho-bien" aria-label="Permalink to &quot;4.1 Các Vùng Xám Phổ biến&quot;">​</a></h3><ul><li><strong>Tổn thất trong tu luyện chiến đấu</strong>: Tu luyện giả có thể gây tổn thất cho nhau trong huấn luyện đối kháng; việc tổn thất này có đạo đức hay không phụ thuộc vào việc cả hai bên đã đồng ý có thông tin hay chưa, và tổn thất có nằm trong phạm vi hợp lý hay không</li><li><strong>Cạnh tranh tài nguyên</strong>: Việc cạnh tranh giữa các tu luyện giả đối với tài nguyên hiếm có đạo đức hay không phụ thuộc vào phương pháp cạnh tranh có công bằng hay không, và có tuân thủ các quy tắc chống độc quyền hay không</li><li><strong>Sự bất đối xứng quyền lực trong mối quan hệ sư phụ-đệ tử</strong>: Giữa sư phụ và đệ tử tự nhiên tồn tại sự bất đối xứng quyền lực; việc sư phụ có lạm dụng quyền lực hay không cần đánh giá cụ thể</li><li><strong>Việc gánh vác rủi ro trong tu luyện</strong>: Một số phương pháp tu luyện bản thân chúng có rủi ro cao; việc tu luyện giả tự nguyện gánh vác rủi ro có đạo đức hay không cần đánh giá về tính thông tin của rủi ro và sự tồn tại của phương pháp thay thế</li><li><strong>Hợp tác tu luyện xuyên chủng tộc</strong>: Hợp tác tu luyện giữa các chủng tộc khác nhau có thể liên quan đến sự khác biệt văn hóa và bất đối xứng quyền lực, cần đánh giá cụ thể</li></ul><h3 id="_4-2-nguyen-tac-xu-ly" tabindex="-1">4.2 Nguyên tắc Xử lý <a class="header-anchor" href="#_4-2-nguyen-tac-xu-ly" aria-label="Permalink to &quot;4.2 Nguyên tắc Xử lý&quot;">​</a></h3><p>Đối với các vấn đề đạo đức trong vùng xám, văn minh cộng sinh áp dụng phương pháp xử lý &quot;phân tích tình huống cụ thể + đánh giá của ủy ban đạo đức + hướng dẫn theo tiền lệ&quot;:</p><ol><li><strong>Phân tích tình huống cụ thể</strong>: Không thực hiện &quot;một kích thước phù hợp với tất cả&quot;; đưa ra phán đoán tổng hợp dựa trên tình huống, động cơ, phương pháp và hậu quả cụ thể</li><li><strong>Đánh giá của ủy ban đạo đức</strong>: Đối với các vấn đề đạo đức phức tạp, trình lên &quot;Ủy ban Đạo đức&quot; trực thuộc Tòa án Neo để đánh giá chuyên môn</li><li><strong>Hướng dẫn theo tiền lệ</strong>: Kết quả đánh giá của ủy ban đạo đức hình thành tiền lệ, cung cấp hướng dẫn cho các vụ án tương tự sau này</li><li><strong>Ưu tiên giáo dục</strong>: Đối với các hành vi không phù hợp trong vùng xám, ưu tiên phương pháp giáo dục và sửa chữa thay vì trừng phạt nghiêm khắc trực tiếp</li><li><strong>Điều chỉnh động</strong>: Cùng với sự phát triển của văn minh và sự sâu sắc của nhận thức đạo đức, tiêu chuẩn phán đoán vùng xám có thể được điều chỉnh động</li></ol><h2 id="_5-giao-duc-va-noi-tai-hoa-đao-đuc-tu-luyen" tabindex="-1">5. Giáo dục và Nội tại hóa Đạo đức Tu luyện <a class="header-anchor" href="#_5-giao-duc-va-noi-tai-hoa-đao-đuc-tu-luyen" aria-label="Permalink to &quot;5. Giáo dục và Nội tại hóa Đạo đức Tu luyện&quot;">​</a></h2><p>Việc duy trì đạo đức tu luyện không thể chỉ dựa vào các biện pháp trừng phạt và giám sát bên ngoài, mà còn cần sự đồng thuận và nội tại hóa từ sâu trong lòng của các tu luyện giả. Văn minh cộng sinh đã xây dựng hệ thống giáo dục đạo đức tu luyện có hệ thống:</p><h3 id="_5-1-giao-duc-co-ban" tabindex="-1">5.1 Giáo dục Cơ bản <a class="header-anchor" href="#_5-1-giao-duc-co-ban" aria-label="Permalink to &quot;5.1 Giáo dục Cơ bản&quot;">​</a></h3><ul><li>Đạo đức tu luyện là khóa học bắt buộc của tất cả các tu luyện giả, và phải nhận được giáo dục đạo đức có hệ thống bắt đầu từ Cảnh giới Cảm Nguyên</li><li>Nội dung giáo dục bao gồm các nguyên tắc đạo đức, danh sách cấm kỵ, phân tích trường hợp, mô phỏng tình huống, v.v.</li><li>Phương pháp giáo dục bao gồm giảng dạy trong lớp, thảo luận trường hợp, đóng vai, sư phụ truyền đạt bằng lời nói và gương mẫu, v.v.</li></ul><h3 id="_5-2-giao-duc-nang-cao" tabindex="-1">5.2 Giáo dục Nâng cao <a class="header-anchor" href="#_5-2-giao-duc-nang-cao" aria-label="Permalink to &quot;5.2 Giáo dục Nâng cao&quot;">​</a></h3><ul><li>Cùng với việc nâng cao cảnh giới của tu luyện giả, độ sâu và phạm vi của giáo dục đạo đức cũng tương ứng nâng cao</li><li>Tu luyện giả cấp cao cần học các vấn đề đạo đức phức tạp hơn (như đạo đức xuyên phạm vi, đạo đức thời gian, đạo đức sáng tạo thế giới, v.v.)</li><li>Tu luyện giả ở Cảnh giới Đạo Nguyên trở lên cần vượt qua &quot;Kiểm tra Đạo đức Cấp cao&quot; mới có thể tiếp tục nâng cao cảnh giới</li></ul><h3 id="_5-3-noi-tai-hoa-trong-thuc-hanh" tabindex="-1">5.3 Nội tại hóa trong Thực hành <a class="header-anchor" href="#_5-3-noi-tai-hoa-trong-thuc-hanh" aria-label="Permalink to &quot;5.3 Nội tại hóa trong Thực hành&quot;">​</a></h3><ul><li>Khuyến khích tu luyện giả thực hành các nguyên tắc đạo đức trong tu luyện hàng ngày, biến các yêu cầu đạo đức thành thói quen hành vi có ý thức</li><li>Thiết lập hệ thống bầu chọn &quot;Mô hình Đạo đức&quot;, tôn vinh các tu luyện giả có thành tích xuất sắc trong lĩnh vực đạo đức tu luyện</li><li>Sư phụ có nghĩa vụ truyền đạt tinh thần đạo đức đồng thời với việc truyền đạt kỹ thuật tu luyện, đạt được &quot;truyền đạt cả đạo và thuật&quot;</li></ul><h2 id="_6-giam-sat-va-thuc-thi-đao-đuc-tu-luyen" tabindex="-1">6. Giám sát và Thực thi Đạo đức Tu luyện <a class="header-anchor" href="#_6-giam-sat-va-thuc-thi-đao-đuc-tu-luyen" aria-label="Permalink to &quot;6. Giám sát và Thực thi Đạo đức Tu luyện&quot;">​</a></h2><h3 id="_6-1-co-che-giam-sat" tabindex="-1">6.1 Cơ chế Giám sát <a class="header-anchor" href="#_6-1-co-che-giam-sat" aria-label="Permalink to &quot;6.1 Cơ chế Giám sát&quot;">​</a></h3><ul><li><strong>Giám sát Mạng lưới Neo</strong>: Mạng lưới neo giám sát liên tục hành vi tu luyện của các tu luyện giả, và đưa ra cảnh báo kịp thời đối với các hành vi bị nghi ngờ vi phạm đạo đức</li><li><strong>Hệ thống Khiếu nại Đạo đức</strong>: Bất kỳ sự sống nào cũng có thể khiếu nại hành vi vi phạm đạo đức tu luyện lên Tòa án Đạo đức của Tòa án Neo, và người khiếu nại được bảo vệ</li><li><strong>Đánh giá Đạo đức Định kỳ</strong>: Tu luyện giả ở Cảnh giới Pháp Nguyên trở lên cần nhận được đánh giá đạo đức một lần mỗi năm, và kết quả đánh giá được ghi vào hồ sơ tu luyện cá nhân</li><li><strong>Giám sát Tổ chức Xã hội</strong>: Khuyến khích các tổ chức tu luyện giả, cộng đồng chủng tộc, v.v. thực hiện giám sát nội bộ đối với đạo đức tu luyện của thành viên của mình</li></ul><h3 id="_6-2-co-che-thuc-thi" tabindex="-1">6.2 Cơ chế Thực thi <a class="header-anchor" href="#_6-2-co-che-thuc-thi" aria-label="Permalink to &quot;6.2 Cơ chế Thực thi&quot;">​</a></h3><ul><li><strong>Tòa án Đạo đức</strong>: Tòa án Đạo đức chuyên biệt trực thuộc Tòa án Neo, chịu trách nhiệm xét xử các vụ án đạo đức tu luyện</li><li><strong>Trừng phạt Phân cấp</strong>: Theo mức độ nghiêm trọng của vi phạm đạo đức, thực hiện các biện pháp trừng phạt phân cấp từ cảnh báo, phạt tiền, khấu trừ giá trị đóng góp, hạn chế quyền tu luyện, bãi bỏ tu vi đến tù chung thân và xử tử hình</li><li><strong>Cải tạo Đạo đức</strong>: Đối với người vi phạm có ý định hối cải, có thể thực hiện cải tạo đạo đức đồng thời với việc trừng phạt; sau khi cải tạo thành công, quyền lợi có thể được phục hồi một phần</li><li><strong>Hồ sơ Tiền án</strong>: Hồ sơ vi phạm đạo đức tu luyện sẽ được ghi vĩnh viễn vào hồ sơ cá nhân, ảnh hưởng đến việc chứng nhận cảnh giới, phân phối tài nguyên, đơn xin chức vụ công cộng, v.v. sau này</li></ul><h2 id="_7-mo-rong-đong-cua-gioi-han-tu-luyen" tabindex="-1">7. Mở rộng Động của Giới hạn Tu luyện <a class="header-anchor" href="#_7-mo-rong-đong-cua-gioi-han-tu-luyen" aria-label="Permalink to &quot;7. Mở rộng Động của Giới hạn Tu luyện&quot;">​</a></h2><p>Đạo đức và giới hạn tu luyện không phải là giáo điều bất biến, mà là các quy phạm sống được điều chỉnh động cùng với sự phát triển của văn minh, tiến bộ của công nghệ, và sự sâu sắc của nhận thức. Văn minh cộng sinh đã xây dựng cơ chế mở rộng động của giới hạn tu luyện:</p><ol><li><strong>Đánh giá Đạo đức Công nghệ Mới</strong>: Mỗi khi xuất hiện công nghệ tu luyện mới hoặc ứng dụng pháp luật mới, trước tiên thực hiện đánh giá đạo đức, và chỉ sau khi vượt qua đánh giá mới có thể phổ biến</li><li><strong>Thảo luận Đạo đức Tình huống Mới</strong>: Khi văn minh bước vào giai đoạn phát triển mới (như thời đại xuyên phạm vi, thời đại liên sao, v.v.), tổ chức thảo luận đạo đức chuyên biệt, xây dựng các quy phạm đạo đức thích ứng với tình huống mới</li><li><strong>Sửa đổi Định kỳ Quy phạm Đạo đức</strong>: Các quy phạm cụ thể của đạo đức tu luyện được sửa đổi một lần mỗi năm năm mươi, và trong quá trình sửa đổi, rộng rãi lắng nghe ý kiến của tất cả các sự sống</li><li><strong>Tích lũy Liên tục Tiền lệ Đạo đức</strong>: Phán quyết của Tòa án Đạo đức hình thành tiền lệ, liên tục làm phong phú và chi tiết hóa nội dung cụ thể của đạo đức tu luyện</li></ol><h2 id="loi-ket" tabindex="-1">Lời kết <a class="header-anchor" href="#loi-ket" aria-label="Permalink to &quot;Lời kết&quot;">​</a></h2><p>Đạo đức và giới hạn tu luyện là trụ cột cốt lõi của văn minh tinh thần Văn minh Cộng sinh Neo. Nó trả lời một câu hỏi cơ bản: &quot;Tu luyện giả nên trở thành người như thế nào?&quot; Câu trả lời của văn minh cộng sinh là: tu luyện giả nên trở thành người có sức mạnh, càng có đạo đức; nên trở thành người thống nhất giữa tiến hóa cá nhân và cộng sinh tất cả các chủng tộc; nên trở thành người theo đuổi sức mạnh nhưng không bao giờ bị sức mạnh nô lệ hóa. Đạo đức tu luyện không phải là sự trói buộc đối với sức mạnh, mà là sự thăng hoa đối với sức mạnh — nó đảm bảo rằng sức mạnh luôn phục vụ phẩm giá sự sống và tiến bộ của văn minh, chứ không trở thành công cụ hủy diệt và cướp bóc. Trong một vũ trụ mà sức mạnh có thể di dời núi non, lấp đầy biển cả, sáng tạo và hủy diệt thế giới, đạo đức tu luyện là tuyến phòng thủ cuối cùng và quan trọng nhất để bảo vệ đường cơ sở của văn minh.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>04-反掠夺主义核心论纲 (Cương lĩnh Cốt lõi Chống Cướp bóc)</li><li>17-位面至高强者标准 (Tiêu chuẩn Người mạnh Tối cao Phạm vi)</li><li>48-司法体系与裁决机制 (Hệ thống Tư pháp và Cơ chế Phán quyết)</li></ul>',56)])])}const s=h(u,[["render",g]]);export{m as __pageData,s as default};
